import{_ as d,c as t,a as s,o as v}from"./index-JS1OG1rP.js";const b={},i={class:"standard-container"};function e(r,a){return v(),t("div",i,[...a[0]||(a[0]=[s('<div class="page-header" data-v-a41db729><h2 data-v-a41db729>RECIST评估标准</h2></div><div class="standard-content" data-v-a41db729><div class="intro-section" data-v-a41db729><h3 data-v-a41db729>关于RECIST标准</h3><p data-v-a41db729> RECIST (Response Evaluation Criteria in Solid Tumors) 是用于评估实体肿瘤治疗效果的标准。 该标准通过测量肿瘤病灶的大小变化来判断治疗反应。 </p></div><div class="criteria-section" data-v-a41db729><h3 data-v-a41db729>评估类别定义</h3><div class="criteria-grid" data-v-a41db729><div class="criteria-card cr" data-v-a41db729><div class="criteria-code" data-v-a41db729>CR</div><div class="criteria-name" data-v-a41db729>完全缓解</div><div class="criteria-desc" data-v-a41db729>所有靶病灶消失，且持续至少4周</div></div><div class="criteria-card pr" data-v-a41db729><div class="criteria-code" data-v-a41db729>PR</div><div class="criteria-name" data-v-a41db729>部分缓解</div><div class="criteria-desc" data-v-a41db729>靶病灶最长径总和减少≥30%，持续至少4周</div></div><div class="criteria-card sd" data-v-a41db729><div class="criteria-code" data-v-a41db729>SD</div><div class="criteria-name" data-v-a41db729>病情稳定</div><div class="criteria-desc" data-v-a41db729>靶病灶变化介于PR和PD之间</div></div><div class="criteria-card pd" data-v-a41db729><div class="criteria-code" data-v-a41db729>PD</div><div class="criteria-name" data-v-a41db729>疾病进展</div><div class="criteria-desc" data-v-a41db729>靶病灶最长径总和增加≥20%且绝对值增加≥5mm，或出现新病灶</div></div></div></div><div class="target-section" data-v-a41db729><h3 data-v-a41db729>靶病灶评估标准</h3><div class="standard-table" data-v-a41db729><table data-v-a41db729><thead data-v-a41db729><tr data-v-a41db729><th data-v-a41db729>评估结果</th><th data-v-a41db729>判断标准</th><th data-v-a41db729>说明</th></tr></thead><tbody data-v-a41db729><tr data-v-a41db729><td data-v-a41db729><span class="status-badge cr" data-v-a41db729>CR</span></td><td data-v-a41db729>所有靶病灶消失</td><td data-v-a41db729>靶病灶最长径总和为0</td></tr><tr data-v-a41db729><td data-v-a41db729><span class="status-badge pr" data-v-a41db729>PR</span></td><td data-v-a41db729>最长径总和减少≥30%</td><td data-v-a41db729>与基线相比，减少≥30%</td></tr><tr data-v-a41db729><td data-v-a41db729><span class="status-badge sd" data-v-a41db729>SD</span></td><td data-v-a41db729>变化介于PR和PD之间</td><td data-v-a41db729>减少&lt;30%且增加&lt;20%</td></tr><tr data-v-a41db729><td data-v-a41db729><span class="status-badge pd" data-v-a41db729>PD</span></td><td data-v-a41db729>最长径总和增加≥20%且绝对值增加≥5mm</td><td data-v-a41db729>同时满足两个条件</td></tr></tbody></table></div></div><div class="non-target-section" data-v-a41db729><h3 data-v-a41db729>非靶病灶评估标准</h3><div class="standard-table" data-v-a41db729><table data-v-a41db729><thead data-v-a41db729><tr data-v-a41db729><th data-v-a41db729>评估结果</th><th data-v-a41db729>判断标准</th></tr></thead><tbody data-v-a41db729><tr data-v-a41db729><td data-v-a41db729><span class="status-badge cr" data-v-a41db729>CR</span></td><td data-v-a41db729>所有非靶病灶消失，且肿瘤标志物水平正常</td></tr><tr data-v-a41db729><td data-v-a41db729><span class="status-badge sd" data-v-a41db729>SD</span></td><td data-v-a41db729>存在一个或多个非靶病灶持续存在，或肿瘤标志物水平高于正常</td></tr><tr data-v-a41db729><td data-v-a41db729><span class="status-badge pd" data-v-a41db729>PD</span></td><td data-v-a41db729>出现一个或多个新病灶，或明确的非靶病灶进展</td></tr></tbody></table></div></div><div class="new-lesion-section" data-v-a41db729><h3 data-v-a41db729>新病灶评估标准</h3><div class="standard-table" data-v-a41db729><table data-v-a41db729><thead data-v-a41db729><tr data-v-a41db729><th data-v-a41db729>评估结果</th><th data-v-a41db729>判断标准</th><th data-v-a41db729>说明</th></tr></thead><tbody data-v-a41db729><tr data-v-a41db729><td data-v-a41db729><span class="status-badge cr" data-v-a41db729>未检出</span></td><td data-v-a41db729>随访影像学检查未发现既往未记录的可疑病灶</td><td data-v-a41db729>不影响整体疗效评价</td></tr><tr data-v-a41db729><td data-v-a41db729><span class="status-badge pd" data-v-a41db729>检出</span></td><td data-v-a41db729>影像学发现既往未记录的可疑病灶</td><td data-v-a41db729>新病灶一经确认，整体评价直接判定为 <span class="status-badge pd" data-v-a41db729>PD</span></td></tr><tr data-v-a41db729><td data-v-a41db729><span class="status-badge pd" data-v-a41db729>确认</span></td><td data-v-a41db729>后续评估中病灶持续存在或明确增大</td><td data-v-a41db729>需排除假阳性或炎症性病灶；不纳入靶病灶最长径总和</td></tr></tbody></table></div></div><div class="overall-section" data-v-a41db729><h3 data-v-a41db729>整体疗效评价规则</h3><div class="rule-list" data-v-a41db729><div class="rule-item" data-v-a41db729><span class="rule-number" data-v-a41db729>1</span><span class="rule-text" data-v-a41db729>只要出现新病灶，整体评价为 <span class="status-badge pd" data-v-a41db729>PD</span></span></div><div class="rule-item" data-v-a41db729><span class="rule-number" data-v-a41db729>2</span><span class="rule-text" data-v-a41db729>非靶病灶明确进展，整体评价为 <span class="status-badge pd" data-v-a41db729>PD</span></span></div><div class="rule-item" data-v-a41db729><span class="rule-number" data-v-a41db729>3</span><span class="rule-text" data-v-a41db729>靶病灶和非靶病灶均CR，整体评价为 <span class="status-badge cr" data-v-a41db729>CR</span></span></div><div class="rule-item" data-v-a41db729><span class="rule-number" data-v-a41db729>4</span><span class="rule-text" data-v-a41db729>靶病灶CR且非靶病灶未进展，整体评价为 <span class="status-badge cr" data-v-a41db729>CR</span></span></div><div class="rule-item" data-v-a41db729><span class="rule-number" data-v-a41db729>5</span><span class="rule-text" data-v-a41db729>靶病灶PR，整体评价为 <span class="status-badge pr" data-v-a41db729>PR</span></span></div><div class="rule-item" data-v-a41db729><span class="rule-number" data-v-a41db729>6</span><span class="rule-text" data-v-a41db729>靶病灶SD，整体评价为 <span class="status-badge sd" data-v-a41db729>SD</span></span></div><div class="rule-item" data-v-a41db729><span class="rule-number" data-v-a41db729>7</span><span class="rule-text" data-v-a41db729>靶病灶PD，整体评价为 <span class="status-badge pd" data-v-a41db729>PD</span></span></div></div></div><div class="notes-section" data-v-a41db729><h3 data-v-a41db729>注意事项</h3><ul data-v-a41db729><li data-v-a41db729>基线评估时需确定靶病灶（最多5个器官，每个器官最多2个病灶）</li><li data-v-a41db729>靶病灶最长径总和用于评估，而非靶病灶仅做定性评估</li><li data-v-a41db729>首次评估需在治疗开始后至少6-8周进行</li><li data-v-a41db729>确认缓解需在首次评估后至少4周再次确认</li><li data-v-a41db729>PD的确认也需要在首次评估后至少4周再次确认（除非出现危及生命的进展）</li></ul></div></div>',2)])])}const l=d(b,[["render",e],["__scopeId","data-v-a41db729"]]);export{l as default};
